mapper.select:
/** * selectTlcmtChgReqstdMngList : isry.couns.mngr.atrzmng.mapper.TlcmtChgReqstdMngMapper : 재택근무지변경신청 목록조회 */ SELECT C##RG.DEC_B64(CC.FLNM_ENCPT) AS APLCNT_NM /** 신청자 이름 **/ , AA.CNSLTNT_ID AS APLCNT_ID /** 신청자 아이디 **/ , AA.HMTRC_WORK_CHG_YMD AS HMTRC_WORK_CHG_YMD /* 재택근무변경일자 */ , TO_CHAR(AA.FRST_REG_DT, 'YYYYMMDD') AS REG_YMD /* 등록일자 */ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 승인상태구분코드 **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_NM , AA.INDEX_SN AS INDEX_SN , COUNT(*) OVER() AS TOTAL_COUNT FROM AYC340 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.DEL_YN = 'N' AND AA.CNSLTNT_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND AA.APRV_STTS_SE_CD = #{aprvSttsSeCd}
AND AA.CNSLTNT_ID = #{userId}
AND CC.FLNM_ENCPT = C##RG.ENC_B64(#{userNm})
AND CC.OGDP_DEPT_CD = #{deptCd}
ORDER BY AA.FRST_REG_DT DESC

mapper.update:
	/**
	*		updateTlcmtChgReqstdMng : isry.couns.mngr.atrzmng.mapper.TlcmtChgReqstdMngMapper : 재택근무지변경신청 수정
	*/
		UPDATE
				AYC340		AA		/** 재택근무지 변경 **/
		SET
				AA.LAST_MDFCN_DT		=	SYSDATE
			,	AA.LAST_MDFR_ID			=	#{loginId}


			,	AA.HMTRC_WORK_CS_CN		=	#{hmtrcWorkCsCn}




			,	AA.HMTRC_WORK_CHG_YMD	=	#{hmtrcWorkChgYmd}




            ,   AA.ZIP                  =   #{zip}




			,	AA.TRPR_ADDR			=	#{trprAddr}




			,	AA.TRPR_LCTN_DADDR		=	#{trprLctnDaddr}




			,	AA.APRV_STTS_SE_CD		=	#{aprvSttsSeCd}




			,	AA.RJCT_CS_CN			=	#{rjctCsCn}



		WHERE	1=1
			AND	AA.INDEX_SN		=	#{indexSn}
